import { MIN_PASSWORD } from "./mappingCrypto";

export type PasswordHint = "short" | "common" | "repeat" | "sequence" | "classes";
export interface PasswordAssessment { ok: boolean; score: 0 | 1 | 2 | 3; hints: PasswordHint[] }

const COMMON = ["password", "motdepasse", "azerty", "qwerty", "123456", "letmein", "welcome", "admin", "legal", "avocat", "lawyer", "dossier", "client", "iloveyou"];

/**
 * Rough heuristic (length x character pool, with pattern penalties). Not a guarantee of strength;
 * encourage a long random passphrase generated by a password manager.
 */
export function assessPassword(pw: string): PasswordAssessment {
  const hints: PasswordHint[] = [];
  const lower = pw.toLowerCase();
  if (pw.length < MIN_PASSWORD) hints.push("short");
  if (COMMON.some(c => lower.includes(c))) hints.push("common");
  if (/(.)\1{3,}/.test(pw)) hints.push("repeat");
  if (/(?:0123|1234|2345|3456|4567|5678|6789|abcd|bcde|cdef|qwer|wert|azer|zert)/i.test(pw)) hints.push("sequence");
  const classes = [/[a-z]/, /[A-Z]/, /\d/, /[^A-Za-z0-9]/].filter(r => r.test(pw)).length;
  if (classes < 3 && pw.length < 20) hints.push("classes");
  const pool = (/[a-z]/.test(pw) ? 26 : 0) + (/[A-Z]/.test(pw) ? 26 : 0) + (/\d/.test(pw) ? 10 : 0) + (/[^A-Za-z0-9]/.test(pw) ? 32 : 0);
  let bits = pw.length * Math.log2(Math.max(pool, 1)) - hints.filter(h => h !== "short" && h !== "classes").length * 20;
  if (new Set(pw).size < pw.length / 2) bits -= 15;
  const score = bits < 45 ? 0 : bits < 65 ? 1 : bits < 85 ? 2 : 3;
  return { ok: pw.length >= MIN_PASSWORD && !hints.includes("common"), score, hints };
}
